def steady_state_error(num=None, den=None, input=None):
    """Steady-state error of a unity-feedback system. The system type, the error constant (Kp, Kv or Ka) and the steady-state error for a unit step, ramp or parabola input.
    Formula: e_{ss} = \\lim_{s\\to 0} \\frac{s\\,R(s)}{1 + G(s)}
    Inputs:
        num: numerator coefficients of the open-loop G(s), highest power of s first
        den: denominator coefficients of G(s), highest power of s first
        input: the test input: unit step 1/s, unit ramp 1/s^2 or unit parabola t^2/2 (1/s^3)
    Outputs: steady_state_error (steady-state error (or 'infinite')), error_constant (position (Kp), velocity (Kv) or acceleration (Ka) error constant), system_type (number of open-loop poles at the origin)
    See also: help("steady_state_error")
    """
    given = {k: v for k, v in dict(num=num, den=den, input=input).items() if v is not None}
    return _P.solve("steady_state_error", **given)

def summing_amplifier(V=None, R=None, Rf=None):
    """Inverting summing amplifier output. The output of an ideal inverting summing amplifier: Vout = -Rf (V1/R1 + V2/R2 + ...).
    Formula: V_{out} = -R_f\\sum_k \\frac{V_k}{R_k}
    Inputs:
        V: input voltages in volts
        R: input resistors in ohms (one per input)
        Rf: feedback resistor
    Outputs: Vout (output voltage), gains (gain of each input, -Rf/R_k)
    See also: help("summing_amplifier")
    """
    given = {k: v for k, v in dict(V=V, R=R, Rf=Rf).items() if v is not None}
    return _P.solve("summing_amplifier", **given)

def temperature_coefficient_from_resistances(R1=None, T1=None, R2=None, T2=None):
    """Temperature coefficient of resistance from two readings. The temperature coefficient of resistance referred to each of two temperatures, from the resistances measured at them.
    Formula: \\alpha_1 = \\frac{R_2 - R_1}{R_1 (T_2 - T_1)}
    Inputs:
        R1: resistance at T1
        T1: first temperature (degrees C accepted in questions)
        R2: resistance at T2
        T2: second temperature
    Outputs: alpha1 (temperature coefficient referred to T1, per K), alpha2 (temperature coefficient referred to T2, per K), slope (change of resistance per kelvin, ohm/K)
    See also: help("temperature_coefficient_from_resistances")
    """
    given = {k: v for k, v in dict(R1=R1, T1=T1, R2=R2, T2=T2).items() if v is not None}
    return _P.solve("temperature_coefficient_from_resistances", **given)

def thevenin_equivalent(netlist=None, node_a=None, node_b=None):
    """Thevenin equivalent of a DC circuit between two nodes. The Thevenin voltage and resistance seen between two nodes of a resistive circuit with independent sources.
    Formula: V_{th} = v_a - v_b\\big|_{open},\\quad R_{th} = \\frac{v_a - v_b}{1\\,\\mathrm{A}}\\big|_{sources\\ off}
    Inputs:
        netlist: elements separated by ';': R<name> <node> <node> <ohms>, V<name> <node+> <node-> <volts>, I<name> <node> <node> <amperes>; node 0 is ground
        node_a: the terminal node (the + side of the equivalent)
        node_b: the reference terminal node
    Outputs: Vth (Thevenin (open-circuit) voltage, node a relative to node b), Rth (Thevenin resistance)
    See also: help("thevenin_equivalent")
    """
    given = {k: v for k, v in dict(netlist=netlist, node_a=node_a, node_b=node_b).items() if v is not None}
    return _P.solve("thevenin_equivalent", **given)

def three_phase_load(VL=None, R=None, X=None, connection=None):
    """Balanced three-phase load (wye or delta). Phase voltage, phase and line currents, real, reactive and apparent power and the power factor of a balanced load with impedance R + jX per phase.
    Formula: P = \\sqrt{3}\\,V_L I_L \\cos\\phi
    Inputs:
        VL: rms line-to-line voltage
        R: resistance per phase
        X: reactance per phase (positive inductive, negative capacitive)
        connection: load connection
    Outputs: phase_voltage (voltage across each phase of the load), phase_current (current in each phase of the load), line_current (current in each line), P (total real power in W), Q (total reactive power in var), S (total apparent power in VA), power_factor (power factor R/|Z|)
    See also: help("three_phase_load")
    """
    given = {k: v for k, v in dict(VL=VL, R=R, X=X, connection=connection).items() if v is not None}
    return _P.solve("three_phase_load", **given)

def transformer(Np=None, Ns=None, Vp=None, RL=None):
    """Ideal transformer: voltages, currents and reflected resistance. Secondary voltage and current, primary current and the load resistance seen from the primary for an ideal transformer with a resistive load.
    Formula: \\frac{V_s}{V_p} = \\frac{N_s}{N_p},\\quad R_{in} = R_L\\left(\\frac{N_p}{N_s}\\right)^2
    Inputs:
        Np: primary turns
        Ns: secondary turns
        Vp: primary (rms) voltage
        RL: load resistance on the secondary
    Outputs: Vs (secondary voltage), Is (secondary (load) current), Ip (primary current), Rin (load resistance reflected to the primary), turns_ratio (Np/Ns)
    See also: help("transformer")
    """
    given = {k: v for k, v in dict(Np=Np, Ns=Ns, Vp=Vp, RL=RL).items() if v is not None}
    return _P.solve("transformer", **given)

def truth_table_sop(expression=None):
    """Truth table and minimal sum of products of a Boolean expression. The minterms (truth table), the canonical sum of products and a minimal sum of products (fewest terms, then fewest literals) of an expression in up to 4 variables.
    Formula: F = \\sum m(\\dots)
    Inputs:
        expression: the expression: AND (&, ·, *), OR (|, +), XOR (^), NOT (~, !, NOT, or a postfix '), parentheses; NOT > AND > XOR > OR
    Outputs: variables (the variables in truth-table order (first = most significant bit)), minterms (rows where the expression is 1), maxterms (rows where it is 0), canonical_sop (sum of all minterms), minimal_sop (a minimal sum of products (A' means NOT A, · means AND)), terms (number of product terms in the minimal form), literals (number of literals in the minimal form)
    See also: help("truth_table_sop")
    """
    given = {k: v for k, v in dict(expression=expression).items() if v is not None}
    return _P.solve("truth_table_sop", **given)

def two_wattmeter(W1=None, W2=None):
    """Three-phase power by the two-wattmeter method. The total power, the power factor, the load angle and the reactive and apparent power of a balanced three-phase load from the readings of two wattmeters.
    Formula: P = W_1 + W_2,\\quad \\tan\\phi = \\sqrt{3}\\,\\frac{W_1 - W_2}{W_1 + W_2}
    Inputs:
        W1: reading of the first wattmeter (negative if it reads backwards)
        W2: reading of the second wattmeter
    Outputs: P (total power W1 + W2), Q (total reactive power in var (magnitude)), S (total apparent power in VA), power_factor (power factor of the load), phase_deg (load angle in degrees (lag or lead needs the phase sequence))
    See also: help("two_wattmeter")
    """
    given = {k: v for k, v in dict(W1=W1, W2=W2).items() if v is not None}
    return _P.solve("two_wattmeter", **given)

def twos_complement_decode(pattern=None):
    """Value of a two's complement bit pattern. The signed value of an n-bit two's complement pattern (n = the number of digits written).
    Formula: x = -b_{n-1}2^{n-1} + \\sum_{i<n-1} b_i 2^i
    Inputs:
        pattern: the bits, most significant first
    Outputs: value (signed value), bits (word width)
    See also: help("twos_complement_decode")
    """
    given = {k: v for k, v in dict(pattern=pattern).items() if v is not None}
    return _P.solve("twos_complement_decode", **given)

def twos_complement_encode(value=None, bits=None):
    """Two's complement representation of a signed integer. The n-bit two's complement bit pattern (and its hexadecimal form) of a signed whole number.
    Formula: x_{2c} = x \\bmod 2^n
    Inputs:
        value: the signed whole number
        bits: word width in bits
    Outputs: pattern (the bit pattern, most significant bit first), hexadecimal (the pattern in hexadecimal), unsigned (the pattern read as an unsigned number)
    See also: help("twos_complement_encode")
    """
    given = {k: v for k, v in dict(value=value, bits=bits).items() if v is not None}
    return _P.solve("twos_complement_encode", **given)

def voltage_divider(Vin=None, R1=None, R2=None):
    """Voltage divider. The output voltage across R2 of two resistors in series across Vin (R1 on top, R2 to ground), and the current.
    Formula: V_{out} = V_{in}\\frac{R_2}{R_1 + R_2}
    Inputs:
        Vin: input voltage
        R1: top resistor (from the input to the output)
        R2: bottom resistor (from the output to ground)
    Outputs: Vout (output voltage across R2 (unloaded)), I (current through the divider)
    See also: help("voltage_divider")
    """
    given = {k: v for k, v in dict(Vin=Vin, R1=R1, R2=R2).items() if v is not None}
    return _P.solve("voltage_divider", **given)

def voltmeter_multiplier(Ifs=None, Rm=None, V=None):
    """Voltmeter multiplier resistance. The series (multiplier) resistance that makes a moving-coil meter of full-scale current Ifs and resistance Rm read a voltage V at full scale, and the voltmeter's sensitivity.
    Formula: R_{mult} = \\frac{V}{I_{fs}} - R_m
    Inputs:
        Ifs: full-scale deflection current of the meter
        Rm: resistance of the meter
        V: required full-scale reading of the voltmeter
    Outputs: Rmult (multiplier (series) resistance), R_total (resistance of the voltmeter), sensitivity (sensitivity in ohm per volt, 1/Ifs), V_fs (full-scale voltage of the bare meter)
    See also: help("voltmeter_multiplier")
    """
    given = {k: v for k, v in dict(Ifs=Ifs, Rm=Rm, V=V).items() if v is not None}
    return _P.solve("voltmeter_multiplier", **given)

def wheatstone_bridge(Vs=None, R1=None, R2=None, R3=None, R4=None):
    """Wheatstone bridge output. The output voltage of a Wheatstone bridge (left arm R1 over R2, right arm R3 over R4, supply Vs), whether it is balanced, and the R4 that balances it.
    Formula: V_{out} = V_s\\left(\\frac{R_2}{R_1+R_2} - \\frac{R_4}{R_3+R_4}\\right)
    Inputs:
        Vs: bridge supply voltage
        R1: left arm, top
        R2: left arm, bottom
        R3: right arm, top
        R4: right arm, bottom
    Outputs: Vout (voltage of the left midpoint relative to the right midpoint), balanced (true when R1 R4 = R2 R3), R4_balance (the R4 that would balance the bridge)
    See also: help("wheatstone_bridge")
    """
    given = {k: v for k, v in dict(Vs=Vs, R1=R1, R2=R2, R3=R3, R4=R4).items() if v is not None}
    return _P.solve("wheatstone_bridge", **given)

def wye_to_delta(Ra=None, Rb=None, Rc=None):
    """Wye-to-delta (T-to-Pi) resistor transformation. The three delta (triangle) resistances equivalent to a wye (star) of resistances at terminals a, b, c.
    Formula: R_{ab} = \\frac{R_aR_b + R_bR_c + R_cR_a}{R_c}
    Inputs:
        Ra: wye arm at terminal a
        Rb: wye arm at terminal b
        Rc: wye arm at terminal c
    Outputs: Rab (delta resistance between a and b), Rbc (delta resistance between b and c), Rca (delta resistance between c and a)
    See also: help("wye_to_delta")
    """
    given = {k: v for k, v in dict(Ra=Ra, Rb=Rb, Rc=Rc).items() if v is not None}
    return _P.solve("wye_to_delta", **given)

def zener_regulator(Vin=None, R=None, Vz=None, RL=None):
    """Zener diode shunt regulator. Load voltage and the currents of a Zener shunt regulator (series resistor R from the input, Zener and load in parallel).
    Formula: I_Z = \\frac{V_{in} - V_Z}{R} - \\frac{V_Z}{R_L}
    Inputs:
        Vin: input voltage
        R: series resistor
        Vz: Zener (breakdown) voltage
        RL: load resistance
    Outputs: VL (load voltage), IR (current in the series resistor), IL (load current), IZ (Zener current), IZ_mA (Zener current in milliamperes), PZ (power dissipated in the Zener)
    See also: help("zener_regulator")
    """
    given = {k: v for k, v in dict(Vin=Vin, R=R, Vz=Vz, RL=RL).items() if v is not None}
    return _P.solve("zener_regulator", **given)


